from normalize import safe_int

def test_safe_int_float_string():
    assert safe_int("3.7") == 3

def test_safe_int_invalid():
    assert safe_int("abc", -1) == -1

def test_safe_int_none():
    assert safe_int(None, -5) == -5

def test_safe_int_padded():
    assert safe_int("  42 ") == 42


from collect import collect_pairs

def test_pairs_no_leak():
    a = collect_pairs([(1, 2)])
    b = collect_pairs([(3, 4)])
    assert a == [(1, 2)]
    assert b == [(3, 4)]

def test_pairs_empty():
    assert collect_pairs([]) == []
